---
name: PR triage

# Fork pull requests get a read-only GITHUB_TOKEN under `pull_request`, which cannot post a
# comment or apply a label. pull_request_target runs with the base repository's permissions
# instead, so it can. This job never checks out or executes the pull request's code — it only
# reads event metadata (PR number, title, author) and calls the GitHub API — so the fork
# cannot influence what runs.
on:
  pull_request_target:
    types: [opened]

permissions: {}

concurrency:
  group: pr-triage-${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  triage:
    name: Triage
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      pull-requests: write
    steps:
      - name: Welcome contributor and apply needs-triage label
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
          PR_AUTHOR: ${{ github.event.pull_request.user.login }}
        with:
          script: |
            const { owner, repo } = context.repo;
            const issue_number = context.payload.pull_request.number;
            const title = process.env.PR_TITLE;
            const author = process.env.PR_AUTHOR;

            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number,
              body: `Welcome, @${author}! Thanks for opening **${title}**. A maintainer will triage this pull request shortly.`,
            });

            try {
              await github.rest.issues.createLabel({
                owner,
                repo,
                name: "needs-triage",
                color: "ededed",
                description: "Needs maintainer triage",
              });
            } catch (error) {
              if (error.status !== 422) {
                throw error;
              }
            }

            await github.rest.issues.addLabels({
              owner,
              repo,
              issue_number,
              labels: ["needs-triage"],
            });

